en.reference:
#include <iostream>
#include <string>
#include <vector>
#include <memory>
#include <iomanip>

class Employee {
protected:
    std::string name;
public:
    Employee(const std::string& name) : name(name) {}
    virtual ~Employee() = default;
    virtual double earnings() const = 0;
    const std::string& getName() const { return name; }
};

class PieceWorker : public Employee {
private:
    double wage;
    int pieces;
public:
    PieceWorker(const std::string& name, double wage, int pieces)
        : Employee(name), wage(wage), pieces(pieces) {}
    double earnings() const override {
        return wage * pieces;
    }
};

class HourlyWorker : public Employee {
private:
    double wage;
    double hours;
public:
    HourlyWorker(const std::string& name, double wage, double hours)
        : Employee(name), wage(wage), hours(hours) {}
    double earnings() const override {
        if (hours <= 40.0) {
            return wage * hours;
        } else {
            return 40.0 * wage + (hours - 40.0) * wage * 1.5;
        }
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int n;
    if (!(std::cin >> n)) return 0;
    std::vector<std::unique_ptr<Employee>> employees;
    for (int i = 0; i < n; ++i) {
        char type;
        std::string name;
        std::cin >> type >> name;
        if (type == 'P') {
            double wage;
            int pieces;
            std::cin >> wage >> pieces;
            employees.push_back(std::make_unique<PieceWorker>(name, wage, pieces));
        } else if (type == 'H') {
            double wage, hours;
            std::cin >> wage >> hours;
            employees.push_back(std::make_unique<HourlyWorker>(name, wage, hours));
        }
    }

    std::cout << std::fixed << std::setprecision(2);
    for (const auto& emp : employees) {
        std::cout << emp->getName() << " " << emp->earnings() << "\n";
    }
    return 0;
}

en.statement:
In C++, the ternary conditional operator `condition ? expr1 : expr2` requires a common static type for the entire expression to be determined at compile time. When one branch has type `int` and the other has type `double`, the usual arithmetic conversions dictate that the entire conditional expression has type `double`.

Write a program that processes $N$ queries. Each query consists of a conditional flag $c$ (where $c \neq 0$ represents `true`, and $c = 0$ represents `false`), an integer $i$ of type `int`, and a floating-point number $d$ of type `double`.

For each query, the program throws an exception (`throw`) which is the result of the conditional expression:
`throw (c ? i : d);`
or `throw (c ? d : i);` depending on the test flag (in this problem, assume the expression is: if $c \neq 0$, take the integer value $i$, otherwise take the floating-point number $d$):
```cpp
try {
    throw (c ? i : d);
}
catch (int val) {
    std::cout << "Caught int: " << val << "\n";
}
catch (double val) {
    std::cout << "Caught double: " << std::fixed << std::setprecision(2) << val << "\n";
}
```

Since the type of the conditional expression is always promoted to `double`, the exception is always caught by the `catch (double)` block. Print the output in the required format for each query.

vi.statement:
Trong C++, toán tử điều kiện ba ngôi `condition ? expr1 : expr2` yêu cầu xác định kiểu tĩnh chung cho toàn bộ biểu thức tại thời điểm biên dịch. Khi một nhánh có kiểu `int` và nhánh còn lại có kiểu `double`, theo các quy tắc chuyển đổi số học chuẩn (usual arithmetic conversions), toàn bộ biểu thức điều kiện sẽ có kiểu `double`.

Hãy viết chương trình nhận vào một số lượng truy vấn $N$. Mỗi truy vấn bao gồm một giá trị cờ điều kiện $c$ (trong đó $c \neq 0$ đại diện cho giá trị `true`, $c = 0$ đại diện cho `false`), một số nguyên $i$ kiểu `int` và một số thực $d$ kiểu `double`.

Với mỗi truy vấn, chương trình ném ngoại lệ (`throw`) là kết quả của biểu thức điều kiện:
`throw (c ? i : d);`
hoặc `throw (c ? d : i);` tùy theo cờ kiểm tra (ở bài toán này giả sử biểu thức là: nếu $c \neq 0$ thì lấy giá trị số nguyên $i$, ngược lại lấy số thực $d$):
```cpp
try {
    throw (c ? i : d);
}
catch (int val) {
    std::cout << "Caught int: " << val << "\n";
}
catch (double val) {
    std::cout << "Caught double: " << std::fixed << std::setprecision(2) << val << "\n";
}
```

Vì kiểu của biểu thức điều kiện luôn được ép sang `double` nên ngoại lệ luôn được khối `catch (double)` bắt. Hãy xuất kết quả theo định dạng yêu cầu cho từng truy vấn.

